seed={(13,4):3,(13,5):5,(13,6):3,(14,5):5,(14,6):3,(15,6):3}
off={(r-14,c-5):v for (r,c),v in seed.items()}
for r,c in marks:
 for (dr,dc),v in off.items():
  rr,cc=r+dr,c+dc
  if 0<=rr<21 and 0<=cc<13:g[rr][cc]=v
# seed itself
for (r,c),v in seed.items():g[r][c]=v
